    "The blood of gods.": "神之血。",
    "The Catacrypts": "地下古墓群",
    "The circle's ward shields you from harm.": "法阵的结界保护你免受伤害。",
    "The conceits of Karnivex were without bounds.": "卡尼维克斯的狂妄无边无际。",
    "The dead can't claim debts.": "死人无法讨债。",
    "The deepest sleep guards the greatest insights.": "最深的沉眠，守护着至高的洞见。",
    "The dragon's eyes begin to open.": "龙的眼睛开始睁开。",
