    "The final step on the twisting stairwell of apprenticeship.": "学徒螺旋阶梯的最后一步。",
    "The flame of life within you refuses to go out.": "你内在的生命之火拒绝熄灭。",
    "The fog here is so thick, you can't see your own hands.": "这里的雾如此浓重，你甚至无法看到自己的手。",
    "The force from the beginning.": "源自太初的力量。",
    "The full weight of a wizard's gaze is often overpowering.": "法师凝视的全部重量往往令人难以承受。",
    "The glass fixes your gaze and stokes your wrath.": "玻璃固定了你的目光，激起你的愤怒。",
    "the gorborung": "戈尔博隆",
    "The Great Bog": "大沼泽",
    "The great dog-like beast is a portent of death.": "巨大的狗状野兽是死亡的预兆。",
    "The guiding hand of fate.": "命运的指引之手。",
    "The halls of the mind are without limits.": "心灵之殿无极限。",
    "The head stone's connected to the... spine stone.": "头部的石头连接到……脊柱的石头。",
