    "The investigation of fire.": "对火的研究。",
    "the irredeemable path": "不可救药之路",
    "The light fantastic.": "奇妙之光。",
    "the lost menagerie": "失落动物园",
    "The magic in your veins.": "流淌在你血脉中的魔法。",
    "The masses of arcane dabblers never reach such heights.": "大量浅尝奥术者从未达到这样的高度。",
    "The mirror shows scenes from far away.": "镜子显示来自远方的场景。",
    "The mirror shows scenes from long ago.": "镜子显示来自很久以前的场景。",
    "The most important part of a proper wizard's stronghold.": "一个合适的法师要塞最重要的部分。",
    "The nothing you've become.": "你化身的虚无。",
    "the old stone": "古老石头",
    "The old stonemasons often chiselled spells into their works.": "古老的石匠们经常将咒语雕刻进他们的作品。",
    "The pesky creatures are everywhere.": "恼人的小怪生灵随处可见。",
    "The pillars broke; the stars fell screaming from the sky.": "支柱断裂，群星尖叫着从天际坠落。",
    "The portal to true magic.": "通往真正魔法的大门。",
    "The powers of creation and destruction, locked in your grip.": "创造与毁灭的力量，尽在你的掌握之中。",
    "The quill lifts off the desk and begins to write...": "羽毛笔从书桌上浮起，开始书写……",
    "The relentless heat of the sun beats down on you.": "太阳无情的热量倾泻在你身上。",
    "The research costs a little more than you expected...": "研究的费用比你预想的要多一点……",
    "The saplings of Yggdrasil become trees to rival mountains.": "尤克特拉希尔的树苗能长成与山争高的巨树。",
    "The scurrying vermin are covered in welts.": "四处奔逃的害虫全身布满脓包。",
    "The secret courtesy that courses like ichor.": "如神血般流淌的秘密恩惠。",
    "The serpent that grips the earth in its scales.": "用鳞片抓住大地的蛇。",
    "The space where a gem once was.": "曾经有一颗宝石的地方。",
    "The stare of the cockatrice is death.": "鸡蛇的凝视就是死亡。",
    "The stars are an open book, to those who can read.": "星辰是一本摊开的书——对那些能读懂的人而言。",
    "The storm before the calm.": "平静前的风暴。",
    "The strongest orc in the whole tribe.": "整个部落中最强的兽人。",
    "The study of air.": "对空气的研究。",
    "The study of physical form.": "对物理形态的研究。",
    "The study of water.": "对水的研究。",
    "The terror before the Wind Age.": "风纪元之前的恐怖。",
    "The uses of these instruments are beyond you.": "这些仪器的用途超出你的理解。",
    "The weight of your will grinds your adversaries away.": "你意志的重量碾碎你的对手。",
    "The whirling chaos above the sea.": "海面上旋转的混沌。",
    "The Wyrd sister Hecubah waits by the roadside.": "命运姐妹赫库芭在路边等待。",
    "Their globed hands glow with pale, unearthly light.": "它们球状的手发出苍白、超自然的光。",
    "There is no safe distance.": "没有安全距离。",
    "There must be a way...": "一定会有办法的……",
    "There was a GEM here. It's gone now.": "这里曾经有颗宝石。现在它不在了。",
    "There's a storm coming.": "暴风雨要来了。",
    "There's another coin down here somewhere...": "这下面某处还有一枚硬币……",
    "These bellows run on their own.": "这风箱自行运转。",
    "These enchanted woods are not particularly dangerous.": "这片附魔林地并不算凶险莫测。",
    "These things seem... vital. Find room for more.": "这些东西似乎……至关重要。腾出更多空间。",
    "They have a cave troll...": "他们有洞穴巨魔……",
    "They seem to be in good spirits": "它们似乎精神不错。",
    "They're tricksy.": "它们狡猾。",
    "They're wild!": "它们是野生的！",
    "thieving": "偷窃",
