    "Extra Combat actions": "额外战斗行动",
    "Equipment crafting": "装备制作",
    "You need that to live!": "你需要那个才能活命！",
    "'Dark and selfish deeds follow you, leaving a stain on your soul.'": "「黑暗与自私的行为跟随你，在你的灵魂上留下污点。」",
    "'Kind and selfless acts can shine a light in the darkest of places.'": "「善良与无私的行为能在最黑暗的地方点亮光芒。」",
    "'You're above this illusion of choice.'": "「你超脱于这种选择的幻象。」",
    "➢ Skills are the principal requirement for most unlocks in Arcanum and typically cost research or arcana to purchase.": "➢ 技能是阿卡纳中大多数解锁的主要条件，通常需要研究点或奥术来购买。",
    "➢ Focus consumes mana to grant skill experience.": "➢ 专注消耗法力来提供技能经验。",
    "➢ Enchants are applied to a piece of equipment to permanently modify it and improve its effectiveness in combat.": "➢ 附魔应用于装备上，永久性地修改它并提高其战斗效能。",
    "➢ Dying in combat has no penalty besides time lost in recuperation.": "➢ 战斗中死亡除了恢复所消耗的时间外没有惩罚。",
    "➢ Levels are a measure of your wizard's experience.": "➢ 等级是衡量你巫师经验的标准。",
    "➢ Adventures are pivotal for progression in Arcanum and often unlock content like upgrades on first completion.": "➢ 冒险对阿卡纳的进展至关重要，首次完成通常会解锁升级等内容。",
    "➢ Dungeons are the primary type of combat adventures.": "➢ 地下城是战斗冒险的主要类型。",
    "➢ Locales are a type of adventure focused on noncombat encounters.": "➢ 地域是一种专注于非战斗遭遇的冒险类型。",
    "➢ Clashes are the type of combat adventure focused on actively fighting a small number of powerful monsters.": "➢ 交锋是一种专注于积极对抗少量强大怪物的战斗冒险类型。",
    "➢ Summons are temporary monsters which assist you in combat.": "➢ 召唤物是在战斗中协助你的临时怪物。",
    "➢ Unlike summons, minions persist between explorations and last as long as they have life.": "➢ 与召唤物不同，仆从在探索之间持续存在，只要他们有生命就能存活。",
    "➢ Companions are a unique type of ally which are automatically generated when you enter combat.": "➢ 伙伴是一种独特的盟友类型，在进入战斗时自动生成。",
    "➢ Classes are Arcanum's primary progression milestones.": "➢ 职业是阿卡纳的主要进展里程碑。",
    "➢ Having learned the fundamentals of magic, it is time to finish your apprenticeship.": "➢ 学会了魔法的基础知识后，是时候完成你的学徒生涯了。",
    "➢ The progression of your wizard's tier of magic can be classified as follows.": "➢ 你巫师的魔法阶层进展可以分类如下。",
    "Sleight of hand, mundane attention manipulation, and other common practices of charlatans and stage performers alike.": "手法技巧、 mundane 注意力操控，以及其他江湖骗子和舞台表演者的常见手法。",
    "A school of magic focused on altering reality to the whims of the wizard.": "一个专注于根据巫师的意愿改变现实的魔法学派。",
    "A school of magic focused on making normally inanimate objects, animate, for the benefit of the wizard.": "一个专注于使通常无生命的物体活化以造福巫师的魔法学派。",
    "A fusion of animation and crafting, this entry-level skill is a prerequisite for advancement in the mechanical arts.": "活化与制作的融合，这个入门级技能是机械艺术进阶的先决条件。",
    "An advanced fusion of animation and crafting, this skill represents an advanced understanding of construct creation.": "活化与制作的高级融合，这个技能代表着对构装体创造的高级理解。",
    "The pinnacle of the crafting/animation arts, this skill represents the capacity to create artificial life.": "制作/活化艺术的顶峰，这个技能代表着创造人工生命的能力。",
    "Puppets are simple constructs that lack any source of internal motive force.": "傀儡是简单的构装体，缺乏任何内部动力来源。",
    "Machinae are automatons capable of performing tasks without direct control.": "机械造物是能够无需直接控制即可执行任务的自动机器。",
    "Automatas are fully sentient artificial constructs, with the cognitive capacity commonly exceeding that of an average human.": "机关是完全有感知能力的人工构装体，其认知能力通常超过普通人类。",
    "➢ Tasks refer to any non-upgrade action which your wizard can perform in the Main Tab.": "➢ 任务指的是你的巫师在主页标签中能够执行的任何非升级行动。",
    "➢ Tasks which consume an action slot will attempt to perpetually perform themselves.": "➢ 消耗行动槽位的任务会尝试永久性地自我执行。",
    "➢ Running tasks priority can be further modified by assigning them as (G)oals or (H)obbies.": "➢ 运行中的任务优先级可以通过将其分配为(G)目标或(H)爱好来进一步调整。",
    "➢ Luck is a stat that causes monsters to drop loot more frequently than normal.": "➢ 幸运是一种属性，使怪物比正常情况下更频繁地掉落战利品。",
    "➢ Almost all forms of inflicting damage available to the player scale with one or more potencies.": "➢ 几乎所有玩家可用的伤害形式都随一种或多种威力属性缩放。",
    "➢ Most sources of damage are assigned a damage type as can be seen in their tooltip.": "➢ 大多数伤害来源都被分配了伤害类型，可以在其工具提示中看到。",
    "➢ Each combat turn, your wizard performs a weapon attack along with casting one spell.": "➢ 每个战斗回合，你的巫师执行一次武器攻击并施放一个法术。",
    "'A truly great mage makes his own spells'.": "「一个真正伟大的法师创造自己的法术。」",
    "➢ The 'Crafting: Arms of Iron' unlocks the Crafting Tab.": "➢ 「制作：钢铁武备」解锁制作标签。",
    "➢ You've managed to reduce your maximum life to zero through penalties!": "➢ 你通过惩罚将最大生命值降低到了零！",
